CREATE TABLE "public"."loans"
(
    "id"               int8                                       NOT NULL GENERATED BY DEFAULT AS IDENTITY (
        INCREMENT 1
MINVALUE  1
MAXVALUE 9223372036854775807
START 1
CACHE 1
),
    "loan_no"          varchar(22) COLLATE "pg_catalog"."default" NOT NULL,
    "borrower_id"      text COLLATE "pg_catalog"."default"        NOT NULL,
    "principal_amount" int8                                       NOT NULL,
    "invested_amount"  int8                                       NOT NULL DEFAULT 0,
    "rate"             numeric(10, 6)                             NOT NULL,
    "roi"              numeric(10, 6)                             NOT NULL,
    "agreement_url"    text COLLATE "pg_catalog"."default"        NOT NULL,
    "status"           varchar(32) COLLATE "pg_catalog"."default" NOT NULL DEFAULT 'PROPOSED'::character varying,
    "created_at"       int8                                       NOT NULL DEFAULT (floor((EXTRACT(epoch FROM clock_timestamp()) * (1000)::numeric)))::bigint,
    "updated_at"       int8                                       NOT NULL DEFAULT (floor((EXTRACT(epoch FROM clock_timestamp()) * (1000)::numeric)))::bigint,
    CONSTRAINT "loans_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "uk_loans_loan_no" UNIQUE ("loan_no"),
    CONSTRAINT "chk_loans_rate" CHECK (rate >= 0:: numeric AND rate <= 100:: numeric
) ,
  CONSTRAINT "chk_loans_principal" CHECK (principal_amount > 0),
  CONSTRAINT "chk_loans_status" CHECK (status::text = ANY (ARRAY['PROPOSED'::character varying, 'APPROVED'::character varying, 'INVESTED'::character varying, 'DISBURSED'::character varying]::text[])),
  CONSTRAINT "chk_loans_roi" CHECK (roi >= 0::numeric AND roi <= rate),
  CONSTRAINT "chk_loans_invested" CHECK (invested_amount >= 0 AND invested_amount <= principal_amount)
)
;

ALTER TABLE "public"."loans"
    OWNER TO "loans";

CREATE INDEX "idx_loans_borrower_id" ON "public"."loans" USING btree (
    "borrower_id" COLLATE "pg_catalog"."default" "pg_catalog"."text_ops" ASC NULLS LAST
    );

COMMENT
ON COLUMN "public"."loans"."id" IS 'Internal database primary key';

COMMENT
ON COLUMN "public"."loans"."loan_no" IS 'Unique business loan number generated from a Base64URL-encoded UUID';

COMMENT
ON COLUMN "public"."loans"."borrower_id" IS 'Borrower identifier';

COMMENT
ON COLUMN "public"."loans"."principal_amount" IS 'Loan principal amount in the smallest currency unit';

COMMENT
ON COLUMN "public"."loans"."invested_amount" IS 'Total invested amount in the smallest currency unit';

COMMENT
ON COLUMN "public"."loans"."rate" IS 'Borrower annual interest rate as a percentage (e.g. 12.5 means 12.5%)';

COMMENT
ON COLUMN "public"."loans"."roi" IS 'Investor annual return rate as a percentage (e.g. 8.75 means 8.75%)';

COMMENT
ON COLUMN "public"."loans"."agreement_url" IS 'URL of the loan agreement document';

COMMENT
ON COLUMN "public"."loans"."status" IS 'Loan lifecycle status: PROPOSED, APPROVED, INVESTED, DISBURSED';

COMMENT
ON COLUMN "public"."loans"."created_at" IS 'Loan creation timestamp in Unix milliseconds';

COMMENT
ON COLUMN "public"."loans"."updated_at" IS 'Last modification timestamp in Unix milliseconds';

COMMENT
ON TABLE "public"."loans" IS 'Loan information and current lifecycle status';



CREATE TABLE "public"."approvals"
(
    "id"              int8                                       NOT NULL GENERATED BY DEFAULT AS IDENTITY (
        INCREMENT 1
MINVALUE  1
MAXVALUE 9223372036854775807
START 1
CACHE 1
),
    "loan_no"         varchar(22) COLLATE "pg_catalog"."default" NOT NULL,
    "employee_id"     text COLLATE "pg_catalog"."default"        NOT NULL,
    "visit_proof_url" text COLLATE "pg_catalog"."default"        NOT NULL,
    "approved_at"     int8                                       NOT NULL,
    "created_at"      int8                                       NOT NULL DEFAULT (floor((EXTRACT(epoch FROM clock_timestamp()) * (1000)::numeric)))::bigint,
    "updated_at"      int8                                       NOT NULL DEFAULT (floor((EXTRACT(epoch FROM clock_timestamp()) * (1000)::numeric)))::bigint,
    CONSTRAINT "approvals_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "fk_approvals_loan_no" FOREIGN KEY ("loan_no") REFERENCES "public"."loans" ("loan_no") ON DELETE NO ACTION ON UPDATE NO ACTION,
    CONSTRAINT "uq_approvals_loan_no" UNIQUE ("loan_no")
)
;

ALTER TABLE "public"."approvals"
    OWNER TO "loans";

CREATE INDEX "idx_approvals_validator_employee_id" ON "public"."approvals" USING btree (
    "employee_id" COLLATE "pg_catalog"."default" "pg_catalog"."text_ops" ASC NULLS LAST
    );

COMMENT
ON COLUMN "public"."approvals"."id" IS 'Internal database primary key';

COMMENT
ON COLUMN "public"."approvals"."loan_no" IS 'Unique business loan number referencing loans.loan_no';

COMMENT
ON COLUMN "public"."approvals"."employee_id" IS 'Employee identifier responsible for approving the loan';

COMMENT
ON COLUMN "public"."approvals"."visit_proof_url" IS 'URL of the loan approval visit proof';

COMMENT
ON COLUMN "public"."approvals"."approved_at" IS 'Loan approval timestamp in Unix milliseconds';

COMMENT
ON COLUMN "public"."approvals"."created_at" IS 'Record creation timestamp in Unix milliseconds';

COMMENT
ON COLUMN "public"."approvals"."updated_at" IS 'Last modification timestamp in Unix milliseconds';

COMMENT
ON TABLE "public"."approvals" IS 'Loan approval records';

CREATE TABLE "public"."disbursements"
(
    "id"                   int8                                        NOT NULL GENERATED BY DEFAULT AS IDENTITY (
        INCREMENT 1
MINVALUE  1
MAXVALUE 9223372036854775807
START 1
CACHE 1
),
    "loan_no"              varchar(22) COLLATE "pg_catalog"."default"  NOT NULL,
    "employee_id"          varchar(128) COLLATE "pg_catalog"."default" NOT NULL,
    "signed_agreement_url" text COLLATE "pg_catalog"."default"         NOT NULL,
    "disbursed_at"         int8                                        NOT NULL,
    "created_at"           int8                                        NOT NULL DEFAULT (floor((EXTRACT(epoch FROM clock_timestamp()) * (1000)::numeric)))::bigint,
    "updated_at"           int8                                        NOT NULL DEFAULT (floor((EXTRACT(epoch FROM clock_timestamp()) * (1000)::numeric)))::bigint,
    CONSTRAINT "pk_disbursements" PRIMARY KEY ("id"),
    CONSTRAINT "fk_disbursements_loan" FOREIGN KEY ("loan_no") REFERENCES "public"."loans" ("loan_no") ON DELETE NO ACTION ON UPDATE NO ACTION,
    CONSTRAINT "uk_disbursements_loan_no" UNIQUE ("loan_no"),
    CONSTRAINT "chk_disbursements_time" CHECK (disbursed_at > 0)
)
;

ALTER TABLE "public"."disbursements"
    OWNER TO "loans";

CREATE TABLE "public"."investments"
(
    "id"              int8                                       NOT NULL GENERATED BY DEFAULT AS IDENTITY (
        INCREMENT 1
MINVALUE  1
MAXVALUE 9223372036854775807
START 1
CACHE 1
),
    "loan_no"         varchar(22) COLLATE "pg_catalog"."default" NOT NULL,
    "investor_id"     text COLLATE "pg_catalog"."default"        NOT NULL,
    "email"           text COLLATE "pg_catalog"."default"        NOT NULL,
    "amount"          int8                                       NOT NULL,
    "idempotency_key" text COLLATE "pg_catalog"."default"        NOT NULL,
    "response"        jsonb                                      NOT NULL,
    "created_at"      int8                                       NOT NULL DEFAULT (floor((EXTRACT(epoch FROM clock_timestamp()) * (1000)::numeric)))::bigint,
    "updated_at"      int8                                       NOT NULL,
    CONSTRAINT "investments_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "fk_investments_loan_no" FOREIGN KEY ("loan_no") REFERENCES "public"."loans" ("loan_no") ON DELETE NO ACTION ON UPDATE NO ACTION,
    CONSTRAINT "uq_investments_idempotency_key" UNIQUE ("idempotency_key"),
    CONSTRAINT "chk_investments_amount" CHECK (amount > 0)
)
;

ALTER TABLE "public"."investments"
    OWNER TO "loans";

CREATE INDEX "idx_investments_loan_no" ON "public"."investments" USING btree (
    "loan_no" COLLATE "pg_catalog"."default" "pg_catalog"."text_ops" ASC NULLS LAST
    );

COMMENT
ON COLUMN "public"."investments"."id" IS 'Internal database primary key';

COMMENT
ON COLUMN "public"."investments"."loan_no" IS 'Business loan number referencing loans.loan_no';

COMMENT
ON COLUMN "public"."investments"."investor_id" IS 'Unique identifier of the investor';

COMMENT
ON COLUMN "public"."investments"."email" IS 'Investor email address for agreement notifications';

COMMENT
ON COLUMN "public"."investments"."amount" IS 'Investment amount in the smallest currency unit';

COMMENT
ON COLUMN "public"."investments"."idempotency_key" IS 'Unique idempotency key used to prevent duplicate investments';

COMMENT
ON COLUMN "public"."investments"."response" IS 'Stored JSON response returned for idempotent retries';

COMMENT
ON COLUMN "public"."investments"."created_at" IS 'Investment creation timestamp in Unix milliseconds';

COMMENT
ON COLUMN "public"."investments"."updated_at" IS 'Last modification timestamp in Unix milliseconds';

COMMENT
ON TABLE "public"."investments" IS 'Investment records for loans';

CREATE TABLE "public"."loan_status_history"
(
    "id"             int8                                       NOT NULL GENERATED BY DEFAULT AS IDENTITY (
        INCREMENT 1
MINVALUE  1
MAXVALUE 9223372036854775807
START 1
CACHE 1
),
    "loan_no"        varchar(22) COLLATE "pg_catalog"."default" NOT NULL,
    "previous_state" text COLLATE "pg_catalog"."default",
    "new_state"      text COLLATE "pg_catalog"."default"        NOT NULL,
    "action"         text COLLATE "pg_catalog"."default"        NOT NULL,
    "created_at"     int8                                       NOT NULL DEFAULT (floor((EXTRACT(epoch FROM clock_timestamp()) * (1000)::numeric)))::bigint,
    CONSTRAINT "loan_status_history_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "fk_history_loan_no" FOREIGN KEY ("loan_no") REFERENCES "public"."loans" ("loan_no") ON DELETE NO ACTION ON UPDATE NO ACTION
)
;

ALTER TABLE "public"."loan_status_history"
    OWNER TO "loans";

CREATE INDEX "idx_history_loan_no" ON "public"."loan_status_history" USING btree (
    "loan_no" COLLATE "pg_catalog"."default" "pg_catalog"."text_ops" ASC NULLS LAST
    );

COMMENT
ON COLUMN "public"."loan_status_history"."id" IS 'Internal database primary key';

COMMENT
ON COLUMN "public"."loan_status_history"."loan_no" IS 'Business loan number referencing loans.loan_no';

COMMENT
ON COLUMN "public"."loan_status_history"."previous_state" IS 'Previous loan status; NULL for initial creation';

COMMENT
ON COLUMN "public"."loan_status_history"."new_state" IS 'New loan status after the transition';

COMMENT
ON COLUMN "public"."loan_status_history"."action" IS 'Action that triggered the status transition';

COMMENT
ON COLUMN "public"."loan_status_history"."created_at" IS 'Status transition timestamp in Unix milliseconds';

COMMENT
ON TABLE "public"."loan_status_history" IS 'Audit history of loan lifecycle status transitions';

CREATE TABLE "public"."notification_outbox"
(
    "id"                int8                                       NOT NULL GENERATED BY DEFAULT AS IDENTITY (
        INCREMENT 1
MINVALUE  1
MAXVALUE 9223372036854775807
START 1
CACHE 1
),
    "loan_no"           varchar(22) COLLATE "pg_catalog"."default" NOT NULL,
    "investor_id"       text COLLATE "pg_catalog"."default"        NOT NULL,
    "email"             text COLLATE "pg_catalog"."default"        NOT NULL,
    "agreement_url"     text COLLATE "pg_catalog"."default"        NOT NULL,
    "notification_type" text COLLATE "pg_catalog"."default"        NOT NULL DEFAULT 'LOAN_FUNDED'::text,
    "lease_token"       text COLLATE "pg_catalog"."default",
    "attempts"          int4                                       NOT NULL DEFAULT 0,
    "available_at"      int8                                       NOT NULL DEFAULT (floor((EXTRACT(epoch FROM clock_timestamp()) * (1000)::numeric)))::bigint,
    "delivered_at"      int8,
    "created_at"        int8                                       NOT NULL DEFAULT ((EXTRACT(epoch FROM clock_timestamp()) * (1000)::numeric))::bigint,
    "updated_at"        int8                                       NOT NULL DEFAULT ((EXTRACT(epoch FROM clock_timestamp()) * (1000)::numeric))::bigint,
    CONSTRAINT "notification_outbox_pkey" PRIMARY KEY ("id"),
    CONSTRAINT "fk_outbox_loan_no" FOREIGN KEY ("loan_no") REFERENCES "public"."loans" ("loan_no") ON DELETE NO ACTION ON UPDATE NO ACTION,
    CONSTRAINT "uq_outbox_notification" UNIQUE ("loan_no", "investor_id", "notification_type"),
    CONSTRAINT "chk_outbox_attempts" CHECK (attempts >= 0),
    CONSTRAINT "chk_outbox_delivered_at" CHECK (delivered_at IS NULL OR delivered_at >= 0)
)
;

ALTER TABLE "public"."notification_outbox"
    OWNER TO "loans";

CREATE INDEX "idx_outbox_pending" ON "public"."notification_outbox" USING btree (
    "available_at" "pg_catalog"."int8_ops" ASC NULLS LAST,
    "id" "pg_catalog"."int8_ops" ASC NULLS LAST
    ) WHERE delivered_at IS NULL;

COMMENT
ON COLUMN "public"."notification_outbox"."id" IS 'Internal primary key';

COMMENT
ON COLUMN "public"."notification_outbox"."loan_no" IS 'Business loan number referencing loans.loan_no';

COMMENT
ON COLUMN "public"."notification_outbox"."investor_id" IS 'Investor identifier';

COMMENT
ON COLUMN "public"."notification_outbox"."email" IS 'Recipient email address';

COMMENT
ON COLUMN "public"."notification_outbox"."agreement_url" IS 'Loan agreement document URL';

COMMENT
ON COLUMN "public"."notification_outbox"."notification_type" IS 'Notification event type';

COMMENT
ON COLUMN "public"."notification_outbox"."lease_token" IS 'Worker lease token used for concurrent processing';

COMMENT
ON COLUMN "public"."notification_outbox"."attempts" IS 'Number of delivery attempts';

COMMENT
ON COLUMN "public"."notification_outbox"."available_at" IS 'Next eligible delivery timestamp in Unix milliseconds';

COMMENT
ON COLUMN "public"."notification_outbox"."delivered_at" IS 'Successful delivery timestamp in Unix milliseconds';

COMMENT
ON COLUMN "public"."notification_outbox"."created_at" IS 'Creation timestamp in Unix milliseconds';

COMMENT
ON COLUMN "public"."notification_outbox"."updated_at" IS 'Last update timestamp in Unix milliseconds';

COMMENT
ON TABLE "public"."notification_outbox" IS 'Transactional outbox for reliable asynchronous loan notifications';